<script lang="ts">export default { inheritAttrs: false };</script>
<script setup lang="ts">
import type { AutoCompleteOption as Option } from './data-types';

import { useAttrs } from 'vue';
import PopupContent from './internal/PopupContent';
import RenderNode from './internal/RenderNode';
import { computed, ref } from 'vue'; import Input from './Input.vue'; import { useFloating, type PopupPlacement } from './internal/floating';
import './styles/auto-complete.css'; import './styles/floating.css';
const attrs = useAttrs();
const props = withDefaults(defineProps<{ options: (string | Option)[]; modelValue?: string; defaultValue?: string; filterOption?: boolean | ((query: string, option: Option) => boolean); highlight?: boolean; size?: 'sm' | 'md' | 'lg'; label?: string; hint?: string; error?: string; allowClear?: boolean; notFoundContent?: string; open?: boolean; defaultOpen?: boolean; placement?: PopupPlacement; popupMatchSelectWidth?: boolean; popupClassName?: string; popupStyle?: import('vue').CSSProperties; popupRender?: (menu: import('vue').VNodeChild) => import('vue').VNodeChild; status?: 'error' | 'warning'; disabled?: boolean; placeholder?: string }>(), { open: undefined, defaultValue: '', filterOption: true, highlight: true, size: 'md', placement: 'bottom-start', popupMatchSelectWidth: true, placeholder: '输入以搜索…' });
const emit = defineEmits<{ 'update:modelValue': [value: string]; change: [value: string]; select: [value: string, option: Option]; search: [query: string]; 'update:open': [value: boolean] }>();
const inner = ref(props.defaultValue), innerOpen = ref(props.defaultOpen ?? false), active = ref(-1); const current = computed(() => props.modelValue ?? inner.value); const options = computed<Option[]>(() => props.options.map(item => typeof item === 'string' ? { value: item, label: item } : item)); const visible = computed(() => options.value.filter(option => props.filterOption === false || !current.value || (typeof props.filterOption === 'function' ? props.filterOption(current.value, option) : `${option.value} ${typeof option.label === 'string' ? option.label : ''}`.toLocaleLowerCase().includes(current.value.toLocaleLowerCase())))); const opened = computed(() => (props.open ?? innerOpen.value) && !props.disabled && (!!visible.value.length || !!props.notFoundContent));
function setOpen(value: boolean) { if (props.disabled) return; if (props.open === undefined) innerOpen.value = value; emit('update:open', value); }
const { anchor, panel, position, id } = useFloating(() => opened.value, () => props.placement, () => setOpen(false), props.popupMatchSelectWidth);
function update(value: string) { if (props.modelValue === undefined) inner.value = value; emit('update:modelValue', value); emit('change', value); emit('search', value); active.value = -1; setOpen(true); }
function choose(option: Option) { if (option.disabled) return; if (props.modelValue === undefined) inner.value = option.value; emit('update:modelValue', option.value); emit('change', option.value); emit('select', option.value, option); setOpen(false); anchor.value?.querySelector('input')?.focus(); }
function key(event: KeyboardEvent) { const enabled = visible.value.map((option, index) => option.disabled ? -1 : index).filter(index => index >= 0); if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) { event.preventDefault(); setOpen(true); if (!enabled.length) return; const at = enabled.indexOf(active.value); active.value = event.key === 'Home' ? enabled[0] : event.key === 'End' ? enabled.at(-1) ?? -1 : enabled[(at + (event.key === 'ArrowDown' ? 1 : -1) + enabled.length) % enabled.length] ?? -1; } if (event.key === 'Enter' && opened.value && visible.value[active.value] && !visible.value[active.value].disabled) { event.preventDefault(); choose(visible.value[active.value]); } if (event.key === 'Tab') setOpen(false); }
</script>
<template><div ref="anchor" :class="[attrs.class, 'at-autocomplete', { 'at-autocomplete--open': opened }]" :style="attrs.style" @keydown="key"><Input v-bind="{ ...attrs, class: undefined, style: undefined }" :model-value="current" :size="size" :label="label" :hint="hint" :error="error" :status="status" :clearable="allowClear" :disabled="disabled" :placeholder="placeholder" role="combobox" autocomplete="off" :aria-expanded="opened" :aria-controls="id" :aria-activedescendant="active >= 0 ? `${id}-${active}` : undefined" @update:model-value="update" @focusin="setOpen(true)"><template v-if="$slots.prefix" #prefix><slot name="prefix" /></template><template v-if="$slots.suffix" #suffix><slot name="suffix" /></template></Input></div><Teleport to="body"><div v-if="opened" ref="panel" :class="['at-popup', 'at-autocomplete__popup', popupClassName]" :style="[position, popupStyle]"><PopupContent :render="popupRender"><slot name="popup"><ul :id="id" role="listbox" class="at-popup__list at-autocomplete__list"><li v-for="(option, index) in visible" :id="`${id}-${index}`" :key="option.value" role="option" :aria-selected="active === index" :aria-disabled="option.disabled" :class="['at-option', { 'at-option--active': active === index, 'at-option--disabled': option.disabled }]" @mousedown.prevent @click="choose(option)" @mouseenter="active = index"><slot name="option" :option="option" :active="active === index" :query="current"><span class="at-option__label"><span><RenderNode :content="option.label ?? option.value" /></span><small v-if="option.description" class="at-option__description"><RenderNode :content="option.description" /></small></span></slot></li><li v-if="!visible.length" class="at-popup__empty">{{ notFoundContent }}</li></ul></slot></PopupContent></div></Teleport></template>
